import random


class MahjongConnect:
    EMPTY_ICON = ' '
    VALID_DIRECTIONS = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def __init__(self, BOARD_SIZE, ICONS):
        self._board_size = BOARD_SIZE
        self._icons = ICONS
        self._board = self._create_board()

    @property
    def board_size(self):
        return self._board_size

    @property
    def icons(self):
        return self._icons

    @property
    def board(self):
        return self._board

    def _create_board(self):
        return [[random.choice(self._icons) for _ in range(self._board_size[1])]
                for _ in range(self._board_size[0])]

    def is_valid_move(self, pos1, pos2):
        if not self._are_positions_valid(pos1, pos2):
            return False
        if pos1 == pos2:
            return False
        if self._board[pos1[0]][pos1[1]] != self._board[pos2[0]][pos2[1]]:
            return False
        return self._has_path(pos1, pos2)

    def _are_positions_valid(self, pos1, pos2):
        x1, y1 = pos1
        x2, y2 = pos2
        return (0 <= x1 < self._board_size[0] and
                0 <= y1 < self._board_size[1] and
                0 <= x2 < self._board_size[0] and
                0 <= y2 < self._board_size[1])

    def _has_path(self, pos1, pos2):
        visited = set()
        stack = [pos1]

        while stack:
            current_pos = stack.pop()
            if current_pos == pos2:
                return True

            if current_pos in visited:
                continue

            visited.add(current_pos)
            x, y = current_pos

            for dx, dy in self.VALID_DIRECTIONS:
                new_pos = (x + dx, y + dy)
                if self._is_in_bounds(new_pos) and new_pos not in visited and \
                        self._board[new_pos[0]][new_pos[1]] == self._board[x][y]:
                    stack.append(new_pos)

        return False

    def _is_in_bounds(self, pos):
        x, y = pos
        return 0 <= x < self._board_size[0] and 0 <= y < self._board_size[1]

    def remove_icons(self, pos1, pos2):
        x1, y1 = pos1
        x2, y2 = pos2
        self._board[x1][y1] = self.EMPTY_ICON
        self._board[x2][y2] = self.EMPTY_ICON

    def is_game_over(self):
        return all(icon == self.EMPTY_ICON for row in self._board for icon in row)
